class Solution {
  public int numMagicSquaresInside(int[][] grid) {
    int ans = 0;
    for (int r = 0; r + 2 < grid.length; r++)
      for (int c = 0; c + 2 < grid[0].length; c++) {
        boolean[] seen = new boolean[10];
        boolean ok = true;
        for (int i = r; i < r + 3 && ok; i++)
          for (int j = c; j < c + 3; j++) {
            int v = grid[i][j];
            if (v < 1 || v > 9 || seen[v]) {
              ok = false;
              break;
            }
            seen[v] = true;
          }
        if (!ok) continue;
        int sum = 15;
        for (int i = 0; i < 3; i++)
          if (grid[r + i][c] + grid[r + i][c + 1] + grid[r + i][c + 2] != sum) ok = false;
        for (int j = 0; j < 3; j++)
          if (grid[r][c + j] + grid[r + 1][c + j] + grid[r + 2][c + j] != sum) ok = false;
        if (grid[r][c] + grid[r + 1][c + 1] + grid[r + 2][c + 2] != sum
            || grid[r][c + 2] + grid[r + 1][c + 1] + grid[r + 2][c] != sum) ok = false;
        if (ok) ans++;
      }
    return ans;
  }
}
